import type { ChatMessage } from '../types/vocational.ts';

// Keep a bounded suffix of the actual exchange; never send welcome/error/fallback
// messages back as if they had been generated by Gemini.
export function buildChatPayload(messages: ChatMessage[]) {
  const eligible = messages.filter((message) => message.role === 'user' ||
    message.source === 'gemini' || message.source === 'gemini-3.8-flash');
  const selected: { role: 'user' | 'assistant'; content: string }[] = [];
  let characters = 0;
  for (let i = eligible.length - 1; i >= 0 && selected.length < 24; i--) {
    const { role, content } = eligible[i];
    if (characters + content.length > 24000) break;
    characters += content.length;
    selected.unshift({ role, content });
  }
  while (selected[0]?.role === 'assistant') selected.shift();
  return { messages: selected };
}
